interface LogBackend {
  log(level: string, message: string, meta?: any): void;
}
interface Formatter {
  format(level: string, message: string, meta?: any): string;
}
class Logger {
  private backends = new Map<string, LogBackend>();
  private formatter: Formatter;
  constructor(formatter: Formatter) { this.formatter = formatter; }
  register(name: string, backend: LogBackend) { this.backends.set(name, backend); }
  unregister(name: string) { this.backends.delete(name); }
  setFormatter(f: Formatter) { this.formatter = f; }
  log(level: string, message: string, meta?: any) {
    const formatted = this.formatter.format(level, message, meta);
    for (const b of this.backends.values()) b.log(level, formatted, meta);
  }
}
```

